from multiprocessing import Process, Value

def worker(v):
    v.value += 1

if __name__ == '__main__':
    v = Value('i', 0, lock=False)
    procs = [Process(target=worker, args=(v,)) for _ in range(2)]
    for p in procs:
        p.start()
    for p in procs:
        p.join()
    print(v.value)

from multiprocessing import Process, Semaphore

def worker(sem):
    sem.acquire()
    print('Acquired')
    sem.release()

if __name__ == '__main__':
    sem = Semaphore(2)
    procs = [Process(target=worker, args=(sem,)) for _ in range(3)]
    for p in procs:
        p.start()
    for p in procs:
        p.join()

