from multiprocessing import Process, Barrier

def worker(b):
    try:
        b.wait(timeout=0.1)
    except:
        print('Timeout')

if __name__ == '__main__':
    b = Barrier(2)
    p = Process(target=worker, args=(b,))
    p.start()
    p.join()
    b.wait()

